  function chainBg(el){
    let bg = 'none'; let node = el;
    while(node && node !== document.documentElement){
      const c = getComputedStyle(node).backgroundColor;
      if(c && c !== 'rgba(0, 0, 0, 0)' && c !== 'transparent'){ bg = c; break; }
      node = node.parentElement;
    }
    return bg;
