  for(const t of themes){
    root.setAttribute('data-theme', t);
    const el = findActive();
    if(!el){ out.push({theme:t, error:'no active item'}); continue; }
    const cs = getComputedStyle(el);
    const svg = el.querySelector('svg');
    out.push({
      theme: t,
      text: el.innerText.trim(),
      classes: el.className,
      color: cs.color,
      bg: cs.backgroundColor,
      parentBg: chainBg(el),
      opacity: cs.opacity,
      svgColor: svg ? getComputedStyle(svg).color : null,
      iconVisible: svg ? getComputedStyle(svg).opacity : null
    });
  }
  root.setAttribute('data-theme', prev);
